```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on XY plane, neck up (+Z)

// ---------- Dimensions (mm) ----------
nut_length     = 12;   // length along X
flange_width   = 10;   // bottom flange width (Y)
flange_thick   = 2;    // flange thickness, z = 0..2
neck_width     = 6;    // neck width (Y), centred
total_height   = 5;    // top of neck (z)
hole_d         = 3.4;  // screw clearance hole diameter
eps            = 0.5;  // cutter overshoot past faces

$fn = 64;

difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);
        // Neck
        translate([-nut_length/2, -neck_width/2, 0])
            cube([nut_length, neck_width, total_height]);
    }
    // Vertical screw hole through centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_height + 2*eps, $fn = 64);
}
```

