```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on the bed (z = 0), neck builds upward (+Z)
// Profile extruded along X, centred on the origin in X and Y

// ---------- Dimensions (mm) ----------
nut_length      = 12;   // length along X
flange_width    = 12;   // bottom flange width (Y)
flange_thick    = 2;    // flange thickness, z = 0 .. 2
neck_width      = 8;    // neck width (Y)
total_height    = 5;    // top of neck (z)
hole_d          = 3.4;  // vertical screw clearance hole diameter
cut_extra       = 0.5;  // overshoot for cutting shapes past faces

$fn = 64;

difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);

        // Centred neck rising to total_height
        translate([-nut_length/2, -neck_width/2, 0])
            cube([nut_length, neck_width, total_height]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = total_height + 2*cut_extra, $fn = 64);
}
