```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with ticks) facing +Z

// ---------- Ring dimensions ----------
outer_d    = 50;    // outer diameter of the ring
inner_d    = 34;    // inner diameter (bore) of the ring
ring_t     = 3;     // ring thickness (Z)

// ---------- Tick mark dimensions ----------
tick_count = 36;    // number of evenly spaced ticks (every 10 deg)
tick_w     = 1;     // groove width (tangential)
tick_depth = 1.5;   // groove depth into top face
tick_len   = 4;     // groove length, measured inward from outer edge
start_ang  = 0;     // first tick on +X axis

// ---------- Helpers ----------
eps        = 0.5;   // overcut past faces to avoid coplanar surfaces
$fn        = 128;   // circle resolution

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_t, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_t + 2 * eps, r = inner_r);
    }

    // Radial tick grooves cut into the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, start_ang + i * 360 / tick_count])
            translate([outer_r - tick_len,
                       -tick_w / 2,
                       ring_t - tick_depth])
                // extends eps past the outer edge and above the top face
                cube([tick_len + eps, tick_w, tick_depth + eps]);
    }
}
```

