// Anti-vibration foot for a benchtop instrument
// Print orientation: wide base on the bed (z = 0), narrowing upward.

$fn = 96;

// ---- Dimensions (mm) ----
base_d      = 30;    // frustum diameter at bottom (z = 0)
top_d       = 22;    // frustum diameter at flat top
height      = 12;    // overall height (top at z = 12)

recess_d    = 24;    // rubber pad recess diameter (bottom face)
recess_h    = 3;     // rubber pad recess depth

screw_d     = 4.5;   // through hole for screw, along Z axis

eps         = 0.5;   // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    // Frustum body
    cylinder(h = height, d1 = base_d, d2 = top_d);

    // Recess in bottom face for rubber pad
    translate([0, 0, -eps])
        cylinder(h = recess_h + eps, d = recess_d);

    // Central screw hole, fully through
    translate([0, 0, -eps])
        cylinder(h = height + 2 * eps, d = screw_d);
}
