```openscad
// Stiffened cover panel: flat plate with 3 transverse ribs
// Print orientation: plate flat on the bed (z = 0), ribs build upward

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness, z = 0 to 2 (mm)

rib_count   = 3;     // number of ribs
rib_thk     = 3;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate, z = 2 to 6 (mm)
rib_pitch   = 30;    // centre-to-centre rib spacing along X (mm)
rib_len     = plate_wid; // ribs run the full width along Y (mm)

overlap     = 0.01;  // small overlap so ribs fuse into the plate (mm)

$fn = 64;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs: centres at x = -30, 0, +30 (outer ribs 30 mm from plate ends)
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_thk/2, -rib_len/2, plate_thk - overlap])
            cube([rib_thk, rib_len, rib_h + overlap]);
    }
}
```

