// Stiffened cover panel
$fn = 64;

// Plate
plate_l = 80;     // plate length along X
plate_w = 60;     // plate width along Y
plate_t = 3;      // plate thickness (z = 0..3)

// Ribs
rib_count = 3;    // number of ribs
rib_t     = 3;    // rib thickness along X
rib_h     = 6;    // rib height above plate (z = 3..9)
rib_pitch = plate_l / (rib_count + 1); // 20 mm centre spacing
overlap   = 0.01; // small overlap into plate for a clean union

union() {
    // Base plate, centred in X/Y
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Ribs at x = -20, 0, +20, running full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = -plate_l/2 + rib_pitch * (i + 1);
        translate([x_c - rib_t/2, -plate_w/2, plate_t - overlap])
            cube([rib_t, plate_w, rib_h + overlap]);
    }
}
