// Powder measuring scoop - hemispherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), opening upward

$fn = 96;

// ---- Bowl ----
bowl_outer_r = 10;    // outer radius of the bowl sphere
bowl_wall    = 2;     // bowl wall thickness
bowl_inner_r = bowl_outer_r - bowl_wall;  // inner radius of the cavity (8 mm)
bowl_cz      = 10;    // sphere centre height, which is also the rim height

// ---- Handle ----
handle_x0    = 8;     // handle start along X
handle_x1    = 90;    // handle end along X
handle_w     = 10;    // handle width in Y
handle_t     = 4;     // handle thickness in Z
handle_top_z = bowl_cz;              // top face is flush with the rim (z = 10)
handle_bot_z = handle_top_z - handle_t; // bottom face at z = 6

eps = 0.5;            // overlap margin for cutting shapes

difference() {
    union() {
        // Lower half of the outer sphere (z = 0 .. 10)
        intersection() {
            translate([0, 0, bowl_cz])
                sphere(r = bowl_outer_r);
            translate([-bowl_outer_r - eps, -bowl_outer_r - eps, -eps])
                cube([2 * (bowl_outer_r + eps),
                      2 * (bowl_outer_r + eps),
                      bowl_cz + eps]);
        }

        // Flat handle running along +X
        translate([handle_x0, -handle_w / 2, handle_bot_z])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Bowl cavity. The full inner sphere reaches past the rim (up to z = 18),
    // so it also opens the top of the bowl.
    translate([0, 0, bowl_cz])
        sphere(r = bowl_inner_r);
}
