cut_overlap  = 0.5;   // extension of cutting shapes past faces [mm]
$fn          = 96;    // curve resolution

// ---------------- Derived ----------------
step = 360 / (2 * n_points);   // angle between successive outline vertices

// Outline vertices: alternate outer/inner, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? r_outer : r_inner,
             a = i * step)
        [r * cos(a), r * sin(a)]
];

// ---------------- Model ----------------
difference() {
    // Star plate
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Centre through-hole
    translate([0, 0, -cut_overlap])
        cylinder(d = hole_d, h = thickness + 2 * cut_overlap, $fn = 96);
}
