        points = [
            // bottom square (z = 0)
            [-base_side/2, -base_side/2, 0],
            [ base_side/2, -base_side/2, 0],
            [ base_side/2,  base_side/2, 0],
            [-base_side/2,  base_side/2, 0],
            // top square (z = height)
            [-top_side/2, -top_side/2, height],
            [ top_side/2, -top_side/2, height],
            [ top_side/2,  top_side/2, height],
            [-top_side/2,  top_side/2, height]
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 5, 1, 0],   // front (-Y)
            [5, 6, 2, 1],   // right (+X)
            [6, 7, 3, 2],   // back (+Y)
            [7, 4, 0, 3],   // left (-X)
            [7, 6, 5, 4]    // top
        ]
    );

    // Centred square pocket in the top face
    translate([-pocket_side/2, -pocket_side/2, height - pocket_depth])
        cube([pocket_side, pocket_side, pocket_depth + eps]);
}
