// Spoked wheel for a small sample cart
// Flat part printed lying on the bed, centred on the origin

$fn = 128;

// ---- Dimensions (mm) ----
wheel_thick   = 8;    // overall thickness of the wheel (Z)
rim_od        = 60;   // rim outer diameter
rim_width     = 4;    // rim radial width
hub_d         = 20;   // hub diameter
axle_d        = 6;    // axle hole diameter
spoke_count   = 8;    // number of spokes
spoke_width   = 4;    // spoke width
eps           = 0.5;  // overcut for clean boolean operations

// ---- Derived ----
rim_or = rim_od / 2;              // rim outer radius
rim_ir = rim_or - rim_width;      // rim inner radius
hub_r  = hub_d / 2;               // hub radius

// Spokes run from inside the hub to inside the rim (overlap for a solid union)
spoke_start = hub_r / 2;                    // starts inside the hub
spoke_len   = (rim_ir + rim_width / 2) - spoke_start; // ends inside the rim

difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(h = wheel_thick, r = rim_or);
            translate([0, 0, -eps])
                cylinder(h = wheel_thick + 2 * eps, r = rim_ir);
        }

        // Hub
        cylinder(h = wheel_thick, r = hub_r);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, wheel_thick]);
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(h = wheel_thick + 2 * eps, d = axle_d);
}
