// Spoked wheel for a small sample cart
// Flat part, lies on the bed (z = 0), centred on the origin

$fn = 128;

// ---- Dimensions (mm) ----
wheel_thk     = 8;    // overall thickness of the wheel (Z)
rim_od        = 80;   // outer diameter of the rim
rim_width     = 4;    // radial width of the rim ring
hub_d         = 14;   // hub outer diameter
axle_d        = 8;    // axle hole diameter (through)
spoke_count   = 6;    // number of spokes
spoke_width   = 5;    // width of each spoke
spoke_start   = 0;    // angle of first spoke (deg, along +X)

// ---- Derived ----
rim_id        = rim_od - 2 * rim_width;   // inner diameter of rim
spoke_overlap = 1;                        // spokes extend into hub/rim for solid union
eps           = 0.5;                      // cutter overshoot

// Spoke runs from hub centre region to inside of rim (with overlap)
spoke_r_in    = hub_d / 2 - spoke_overlap;
spoke_r_out   = rim_id / 2 + spoke_overlap;

difference() {
    union() {
        // Outer rim ring
        difference() {
            cylinder(d = rim_od, h = wheel_thk);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = wheel_thk + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = wheel_thk);

        // Radial spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([spoke_r_in, -spoke_width / 2, 0])
                    cube([spoke_r_out - spoke_r_in, spoke_width, wheel_thk]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_thk + 2 * eps);
}
